from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    edge_counts = Counter(g[r][c] for r in range(h) for c in range(w)
                          if (r == 0 or r == h-1 or c == 0 or c == w-1) and g[r][c] != bg)
    border = edge_counts.most_common(1)[0][0]
    inks = [v for v in counts if v not in (bg, border)]
    if not inks:
        return g
    ink = max(inks, key=lambda v: counts[v])
    edge_cells = {(r,c) for r in range(h) for c in range(w)
                  if g[r][c] == border and (r == 0 or r == h-1 or c == 0 or c == w-1)}
    seen=set(); comps=[]
    for start in edge_cells:
        if start in seen: continue
        stack=[start]; seen.add(start); comp=[]
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in edge_cells and (nr,nc) not in seen:
                    seen.add((nr,nc)); stack.append((nr,nc))
        comps.append(comp)
    for comp in comps:
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        horizontal = (max(cs)-min(cs) >= max(rs)-min(rs))
        has_corner = any(r in (0,h-1) and c in (0,w-1) for r,c in comp)
        for r,c in comp:
            if horizontal:
                dr,dc = (1,0) if r == 0 else (-1,0)
                ray_vertical = True
                if has_corner:
                    # Large corner bars project their whole span; a short one only
                    # projects at its corner cell.
                    fire = len(comp) >= 4 or (r in (0,h-1) and c in (0,w-1))
                else:
                    fire = any(g[rr][c] == ink for rr in range(h))
            else:
                dr,dc = (0,1) if c == 0 else (0,-1)
                ray_vertical = False
                offset = r - min(rs)
                marker_on_ray = False
                rr,cc=r+dr,c+dc
                while 0 <= rr < h and 0 <= cc < w:
                    if g[rr][cc] == ink:
                        marker_on_ray=True; break
                    rr+=dr; cc+=dc
                if has_corner:
                    fire = (len(comp) % 2 == 1) or (offset % 2 == 0)
                else:
                    fire = marker_on_ray
            if not fire:
                continue
            rr,cc=r+dr,c+dc
            while 0 <= rr < h and 0 <= cc < w:
                # Long horizontal edge bars leave the far boundary row untouched.
                if ray_vertical and len(comp) >= 4 and rr in (0,h-1):
                    break
                if g[rr][cc] == ink:
                    g[rr][cc] = 4
                    break
                if g[rr][cc] == bg:
                    g[rr][cc] = ink
                else:
                    break
                rr+=dr; cc+=dc
    return g

